import numbers
from typing import Dict, Any, List, Optional

def handler(event: Dict[str, Any]):
    """
    风险评估函数，根据参数和规则决策，返回最终风险级别

    Parameters:
    event: dict
        - arguments: dict, 待评估的数据参数
        - rules: list, 风险规则列表
        - param_defs: list, 参数定义列表

    Return:
    dict: 包含最终风险级别的结果
    """
    try:
        # 1. 参数提取与校验
        arguments = event.get("arguments", {})
        rules = event.get("rules", [])
        param_defs = event.get("param_defs", [])

        # 风险级别定义
        risk_levels = ["safe", "low", "medium", "high", "critical"]
        risk_level_order = {level: idx for idx, level in enumerate(risk_levels)}

        max_level = "safe"
        message = ""

        for rule in rules:
            # 无 when 条件时取 decision
            if rule.get("when") is None:
                decision = rule.get("decision", "")
                if decision and risk_level_order.get(decision, -1) > risk_level_order.get(max_level, -1):
                    max_level = decision
                    message = rule.get("message", "")
                continue

            # 仅支持 when.type=condition
            if rule["when"].get("type") != "condition":
                # natural_language 等暂不评估，视为不命中
                continue

            # when.condition 为空时视为满足
            if rule["when"].get("condition") is None:
                decision = rule.get("decision", "")
                if decision and risk_level_order.get(decision, -1) > risk_level_order.get(max_level, -1):
                    max_level = decision
                    message = rule.get("message", "")
                continue

            # 评估条件
            satisfies, err = evaluate_data_against_condition(arguments, rule["when"]["condition"], param_defs)
            if err:
                print(f"EvaluateDataAgainstCondition failed for rule {rule.get('id', 'unknown')}: {err}")
                continue

            decision = rule.get("decision", "")
            if satisfies and decision and risk_level_order.get(decision, -1) > risk_level_order.get(max_level, -1):
                max_level = decision
                message = rule.get("message", "")

        return {"risk_level": max_level, "success": True, "message": message}

    except Exception as e:
        import traceback
        print(traceback.format_exc())
        return {
            "error": f"Execution Error: {str(e)}",
            "success": False
        }

def evaluate_data_against_condition(data: Dict[str, Any], condition: Dict[str, Any], param_defs: List[Dict[str, Any]]) -> tuple[bool, Optional[str]]:
    """判断数据是否满足条件"""
    if condition is None:
        return True, None

    prop_map = {}
    for param in param_defs:
        prop_map[param["name"]] = {
            "name": param["name"],
            "type": param.get("type", "")
        }

    return evaluate_condition_recursive(data, condition, prop_map)

def evaluate_condition_recursive(instance_data: Dict[str, Any], condition: Dict[str, Any], prop_map: Dict[str, Any]) -> tuple[bool, Optional[str]]:
    """递归评估条件"""
    if condition is None:
        return True, None

    operation = condition.get("operation", "")

    # 处理逻辑运算符
    if operation == "and":
        for sub_cond in condition.get("sub_conditions", []):
            result, err = evaluate_condition_recursive(instance_data, sub_cond, prop_map)
            if err:
                return False, err
            if not result:
                return False, None
        return True, None

    elif operation == "or":
        for sub_cond in condition.get("sub_conditions", []):
            result, err = evaluate_condition_recursive(instance_data, sub_cond, prop_map)
            if err:
                return False, err
            if result:
                return True, None
        return False, None

    # 处理字段基础运算符
    field_name = condition.get("field") or ""
    field_value = instance_data.get(field_name)
    field_exists = field_name in instance_data

    # 处理不需要字段存在的运算符
    if operation == "exist":
        return field_exists, None
    elif operation == "not_exist":
        return not field_exists, None
    elif operation == "empty":
        if not field_exists:
            return True, None
        return is_empty(field_value), None
    elif operation == "not_empty":
        if not field_exists:
            return False, None
        return not is_empty(field_value), None

    # 对于其他运算符，字段必须存在（除了 != 可以在字段不存在时返回 True）
    if not field_exists:
        if operation == "!=":
            return True, None
        return False, None

    # 获取属性信息用于类型检查
    prop = prop_map.get(field_name, {})
    field_type = prop.get("type", "")

    # 基于操作符进行评估
    condition_value = condition.get("value")
    if operation == "==":
        return compare_values(field_value, condition_value, "==", field_type)
    elif operation == "!=":
        return compare_values(field_value, condition_value, "!=", field_type)
    elif operation == ">":
        return compare_values(field_value, condition_value, ">", field_type)
    elif operation == ">=":
        return compare_values(field_value, condition_value, ">=", field_type)
    elif operation == "<":
        return compare_values(field_value, condition_value, "<", field_type)
    elif operation == "<=":
        return compare_values(field_value, condition_value, "<=", field_type)
    elif operation == "in":
        return evaluate_in(field_value, condition_value)
    elif operation == "not_in":
        result, err = evaluate_in(field_value, condition_value)
        if err:
            return False, err
        return not result, None
    elif operation == "range":
        return evaluate_range(field_value, condition_value, field_type, True)
    elif operation == "out_range":
        result, err = evaluate_range(field_value, condition_value, field_type, True)
        if err:
            return False, err
        return not result, None
    elif operation == "true":
        return is_true(field_value), None
    elif operation == "false":
        return is_false(field_value), None
    elif operation == "before":
        return evaluate_before(field_value, condition_value)
    elif operation == "between":
        return evaluate_range(field_value, condition_value, field_type, False)
    else:
        return False, f"unsupported operation: {operation}"

def is_empty(value: Any) -> bool:
    """检查值是否为空"""
    if value is None:
        return True

    if isinstance(value, str):
        return value == ""
    elif isinstance(value, (list, tuple, dict)):
        return len(value) == 0

    return False

def is_true(value: Any) -> bool:
    """检查值是否为布尔真"""
    return isinstance(value, bool) and value

def is_false(value: Any) -> bool:
    """检查值是否为布尔假"""
    return isinstance(value, bool) and not value

def evaluate_in(field_value: Any, value_list: Any) -> tuple[bool, Optional[str]]:
    """检查 field_value 是否在值列表中"""
    if value_list is None:
        return False, None

    if not isinstance(value_list, list):
        return False, "in operation requires array value"

    for v in value_list:
        if compare_values_simple(field_value, v):
            return True, None
    return False, None

def evaluate_range(field_value: Any, range_value: Any, field_type: str, left_closed_right_open: bool) -> tuple[bool, Optional[str]]:
    """检查 field_value 是否在范围内"""
    if range_value is None:
        return False, None

    if not isinstance(range_value, list) or len(range_value) != 2:
        return False, "range operation requires array of length 2"

    min_val, max_val = range_value

    # 比较 field_value 与最小值
    min_result, err = compare_values(field_value, min_val, ">=", field_type)
    if err:
        return False, err
    if not min_result:
        return False, None

    # 比较 field_value 与最大值
    if left_closed_right_open:
        max_result, err = compare_values(field_value, max_val, "<", field_type)
        if err:
            return False, err
        return max_result, None
    else:
        max_result, err = compare_values(field_value, max_val, "<=", field_type)
        if err:
            return False, err
        return max_result, None

def evaluate_before(field_value: Any, condition_value: Any) -> tuple[bool, Optional[str]]:
    """检查 field_value (日期) 是否在 condition_value 之前"""
    try:
        field_time = parse_time(field_value)
        cond_time = parse_time(condition_value)
        return field_time < cond_time, None
    except Exception as e:
        return False, str

def compare_values(left, right, operation, field_type=""):
    if left is None or right is None:
        return False, None

    if field_type == "datetime":
        try:
            left_time = _parse_time(left)
            right_time = _parse_time(right)
        except ValueError as e:
            return False, str(e)
        if operation == "==":
            return left_time == right_time, None
        if operation == "!=":
            return left_time != right_time, None
        if operation == ">":
            return left_time > right_time, None
        if operation == ">=":
            return left_time >= right_time, None
        if operation == "<":
            return left_time < right_time, None
        if operation == "<=":
            return left_time <= right_time, None

    if _is_numeric(left) and _is_numeric(right):
        ln = _to_float64(left)
        rn = _to_float64(right)
        if operation == "==":
            return ln == rn, None
        if operation == "!=":
            return ln != rn, None
        if operation == ">":
            return ln > rn, None
        if operation == ">=":
            return ln >= rn, None
        if operation == "<":
            return ln < rn, None
        if operation == "<=":
            return ln <= rn, None

    left_str = str(left)
    right_str = str(right)
    if operation == "==":
        return left_str == right_str, None
    if operation == "!=":
        return left_str != right_str, None
    if operation == ">":
        return left_str > right_str, None
    if operation == ">=":
        return left_str >= right_str, None
    if operation == "<":
        return left_str < right_str, None
    if operation == "<=":
        return left_str <= right_str, None

    return False, f"unsupported operation: {operation}"

def _is_numeric(value):
    return isinstance(value, numbers.Number) and not isinstance(value, bool)

def _to_float64(value):
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return float(value)
    return 0.0
